class CookieJar {
    int cookies = 10;
    void takeCookie() {
        cookies--; // Two threads doing this at once cause a Race Condition
    }
}

class CookieJar {
    private int cookies = 10;
    // Only one thread can enter this 'room' at a time
    public synchronized void takeSafeCookie() {
        if(cookies > 0) cookies--;
    }
}

